function executeSkill(context) {
  var caster = context.piece; var player = battle.players.find(function(p) { return p.playerId === caster.ownerPlayerId; });
  if (!player) return { success: false, message: '未找到玩家' };
  function isOrdinaryHoly(card) {
  return card && ['holy-smite', 'holy-heal', 'holy-charge'].indexOf(card.cardId) !== -1;
}
  var eligible = player.hand.filter(function(card) { return isOrdinaryHoly(card) && !card.holyProphecy && !card.holyProphecyEnhanced; });
  if (eligible.length === 0) return { success: false, message: '没有可预言的圣光手牌' };
  var options = eligible.map(function(card) { return { label: (card.name || card.cardId) + '（' + card.instanceId + '）', value: card.instanceId }; });
  var choice = selectOption({ title: '圣光预言：选择一张圣光手牌', options: options });
  if (choice === undefined || choice === null || choice.needsOptionSelection) return choice;
  var card = eligible.find(function(item) { return item.instanceId === choice; });
  if (!card) return { success: false, message: '选择的手牌已无法被预言' };
  card.holyProphecy = { sourcePieceId: caster.instanceId, createdTurnNumber: battle.turn.turnNumber };
  return { success: true, message: caster.name + '为' + (card.name || card.cardId) + '留下了圣光预言' };
}
